import{_ as r,o as t,c as o,a2 as a}from"./chunks/framework.DdtnLau3.js";const d=JSON.parse('{"title":"规范","description":"","frontmatter":{},"headers":[],"relativePath":"zh/spec/index.md","filePath":"zh/spec/index.md"}'),s={name:"zh/spec/index.md"};function i(p,e,n,h,b,c){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="规范" tabindex="-1">规范 <a class="header-anchor" href="#规范" aria-label="Permalink to &quot;规范&quot;">​</a></h1><p>这些页面面向开发者，总结当前 Piwork 实现，依据源码项目已有规范编写，不另行定义 API 或包格式。</p><p>当前交付为 <a href="https://github.com/pphboy/piwork/releases/tag/v0.0.2" target="_blank" rel="noreferrer">Piwork 0.0.2 Preview</a>，包含 Web base 与直接模型管理。五角色镜像已发布并匿名拉取/执行核验，固定身份见<a href="/piwork/piwork/install/0.0.2-fb4f577da3b4-512ec778b267/release-manifest.json">发行清单</a>。干净构建源码为 <code>fb4f577da3b4d0008b97a59103b84efefbf9b508</code>，输入摘要为 <code>512ec778b2671454ce1e66ceb11893f4f3ff908286ec2ae4947fd24fda100f37</code>；发行 tag 另包含发布材料更新，不改写镜像构建身份。Web base 保留独立<a href="/piwork/piwork/install/0.0.2-fb4f577da3b4-512ec778b267/web-base-release.json">已发布记录</a>。Windows 原生客户端继续以实验性程序交付，完整正式验收未完成；实际范围见 Release 附件 preview-verification.md。旧下载目录保留历史归属。</p><table tabindex="0"><thead><tr><th>范围</th><th>本站文档</th><th>权威来源</th></tr></thead><tbody><tr><td>可携带 Work</td><td><a href="/piwork/zh/spec/work.html">Work 规范</a></td><td><a href="https://github.com/pphboy/piwork/blob/main/docs/work-package-format.md" target="_blank" rel="noreferrer">包格式</a>与 <a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/portable-work/spec.md" target="_blank" rel="noreferrer">portable-work</a></td></tr><tr><td>受管理能力</td><td><a href="/piwork/zh/spec/service.html">Service 规范</a></td><td><a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/work-services/spec.md" target="_blank" rel="noreferrer">work-services</a>与 <a href="https://github.com/pphboy/piwork/blob/main/internal/servicemcp/tools.json" target="_blank" rel="noreferrer">MCP 工具</a></td></tr><tr><td>智能执行</td><td><a href="/piwork/zh/spec/harness.html">Harness 规范</a></td><td><a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/agent-conversation/spec.md" target="_blank" rel="noreferrer">agent-conversation</a>与 <a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/piwork-brain/spec.md" target="_blank" rel="noreferrer">piwork-brain</a></td></tr></tbody></table><h2 id="状态标记" tabindex="-1">状态标记 <a class="header-anchor" href="#状态标记" aria-label="Permalink to &quot;状态标记&quot;">​</a></h2><ul><li><strong>当前行为 / 格式：</strong> 已实现的行为和源码契约。</li><li><strong>实验性：</strong> 已有实现，但契约和交互还在演进。</li><li><strong>未来方向：</strong> 产品目标，不是已实现的保证。</li></ul><p>遇到不一致时，以当前实现为准。可以<a href="https://github.com/pphboy/piwork/issues" target="_blank" rel="noreferrer">提交 Issue</a>，附上命令、镜像版本和实际结果。</p><h2 id="当前交付边界" tabindex="-1">当前交付边界 <a class="header-anchor" href="#当前交付边界" aria-label="Permalink to &quot;当前交付边界&quot;">​</a></h2><p>Core 通过 Unix API 管理一台本地 Linux Docker Engine。Docker 交付面向 <code>linux/amd64</code> 和 Engine 28+；仅 Core Compose Demo 或高级 Compose 部署另需 Compose 2.24+。Go CLI 有 Windows 和 Linux 构建目标；尚未完成的原生 Windows 验收项见源码的 <a href="https://github.com/pphboy/piwork/blob/main/docs/cli-platforms.md" target="_blank" rel="noreferrer">CLI 平台指南</a>。</p><p>Work 需要就绪的运行镜像和模型配置。Core 关闭时会停止受管理的运行容器，并保留持久状态。关闭 Desktop 或 CLI 不会停止 Work。</p><p><a href="/piwork/zh/guide/quick-start.html">终端 Quick Start</a> 使用独立 Core/CLI 镜像，Core 可单独采用 Compose；合并方式见单机部署示例，原生构建与管理员操作见独立导航。</p>',11)])])}const f=r(s,[["render",i]]);export{d as __pageData,f as default};
